import React from "react";
import "./style.css";
const CustomCursor = (props) => {
  const secondaryCursor = React.useRef(null);
  const positionRef = React.useRef({
    mouseX: 0,
    mouseY: 0,
    destinationX: 0,
    destinationY: 0,
    distanceX: 0,
    distanceY: 0,
    key: -1,
  });

  // ::: Code Generated by Copilot d5f7b9c1-3e4a-4c6e-8a0d-2b4f6d8a0c5e. This comment will be removed automatically after the file is saved :::
  // The follow loop runs only while the cursor is catching up, instead of every frame forever
  React.useEffect(() => {
    const position = positionRef.current;

    const followMouse = () => {
      position.key = -1;
      const {
        mouseX,
        mouseY,
        destinationX,
        destinationY,
        distanceX,
        distanceY,
      } = position;
      let settled = false;
      if (!destinationX || !destinationY) {
        position.destinationX = mouseX;
        position.destinationY = mouseY;
        settled = true;
      } else {
        position.distanceX = (mouseX - destinationX) * 0.1;
        position.distanceY = (mouseY - destinationY) * 0.1;
        if (
          Math.abs(position.distanceX) +
            Math.abs(position.distanceY) <
          0.1
        ) {
          position.destinationX = mouseX;
          position.destinationY = mouseY;
          settled = true;
        } else {
          position.destinationX += distanceX;
          position.destinationY += distanceY;
        }
      }
      if (secondaryCursor && secondaryCursor.current)
        secondaryCursor.current.style.transform = `translate3d(${destinationX}px, ${destinationY}px, 0)`;
      if (!settled || destinationX !== position.destinationX || destinationY !== position.destinationY) {
        position.key = requestAnimationFrame(followMouse);
      }
    };

    const handleMouseMove = (event) => {
      const { clientX, clientY } = event;

      const mouseX = clientX;
      var mouseY = clientY;
      if(props.down===false){
        mouseY = clientY;
      }
      else{
        mouseY = clientY - 85;
      }

      position.mouseX =
        mouseX - secondaryCursor.current.clientWidth / 2;
      position.mouseY =
        mouseY - secondaryCursor.current.clientHeight / 2;

      if (position.key === -1) {
        position.key = requestAnimationFrame(followMouse);
      }
    };

    document.addEventListener("mousemove", handleMouseMove, { passive: true });

    return () => {
      document.removeEventListener("mousemove", handleMouseMove);
      cancelAnimationFrame(position.key);
      position.key = -1;
    };
  }, [props.down]);
  return (
    <div className={`cursor-wrapper default`}>
      <div className="secondary-cursor" ref={secondaryCursor}></div>
    </div>
  );
};

export default CustomCursor;